}

interface SwitchProps {
  children?: ReactNode | ((values: SwitchRenderProps) => ReactNode)
  className?: string
  size?: SwitchSize
  isSelected?: boolean
  defaultSelected?: boolean
  onChange?: (isSelected: boolean) => void
  isDisabled?: boolean
  isInvalid?: boolean
  isReadOnly?: boolean
  isRequired?: boolean
  name?: string
  value?: string
  "aria-label"?: string
  id?: string
  render?: (props: Record<string, unknown>) => ReactNode
}

function Switch({
  children,
  className,
  size = "md",
  isSelected: isSelectedProp,
  defaultSelected = false,
  onChange,
  isDisabled = false,
  isInvalid = false,
  isReadOnly = false,
  isRequired = false,
  name,
  value = "on",
  render,
  ...aria
}: SwitchProps) {
  const [internalSelected, setInternalSelected] = useState(defaultSelected)
  const isSelected = isSelectedProp ?? internalSelected

  const setSelected = (v: boolean) => {
    setInternalSelected(v)
    onChange?.(v)
  }

  const renderProps: SwitchRenderProps = {
    isSelected,
    isDisabled,
    isReadOnly,
    isInvalid,
    isRequired,
  }

  const contextValue: SwitchContextValue = { ...renderProps, setSelected, size }

  const rootProps: Record<string, unknown> = {
