/**
 * Modal
 * Saf React bileşen (bağımlılıksız).
 * Odaklı etkileşimler için diyalog katmanı — Trigger/Backdrop/Container/Dialog compound.
 *   <Modal>
 *     <Button>Open Modal</Button>
 *     <ModalBackdrop>
 *       <ModalContainer>
 *         <ModalDialog>
 *           <ModalCloseTrigger />
 *           <ModalHeader><ModalIcon>…</ModalIcon><ModalHeading>Başlık</ModalHeading></ModalHeader>
 *           <ModalBody>…</ModalBody>
 *           <ModalFooter><Button slot="close">Kapat</Button></ModalFooter>
 *         </ModalDialog>
 *       </ModalContainer>
 *     </ModalBackdrop>
 *   </Modal>
 * Özellikler: size (xs..full) · placement (auto/center/top/bottom) · scroll
 * (inside/outside) · backdrop variant (opaque/blur/transparent) · isDismissable ·
 * isKeyboardDismissDisabled · kontrollü (isOpen/onOpenChange) · portal ·
 * Dialog children render fn ({close}) · slot="close" otomatik kapatma ·
 * ESC + scroll lock + giriş animasyonu (tw-animate-css).
 * @id 432
 * @category Overlay
 * @subcategory Modal
 */
import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactElement,
  type ReactNode,
} from "react"
import { createPortal } from "react-dom"
import { cn } from "@/lib/utils"
import { X } from "@/components/ui/icons"

/* ---------- Types ---------- */

type BackdropVariant = "opaque" | "blur" | "transparent"
type ModalPlacement = "auto" | "center" | "top" | "bottom"
type ModalSize = "xs" | "sm" | "md" | "lg" | "cover" | "full"
type ModalScroll = "inside" | "outside"

interface OverlayState {
  isOpen: boolean
  open: () => void
  close: () => void
  toggle: () => void
  setOpen: (v: boolean) => void
}

/** kütüphane useOverlayState karşılığı — saf React hook */
function useOverlayState({ defaultOpen = false, onOpenChange }: { defaultOpen?: boolean; onOpenChange?: (v: boolean) => void } = {}): OverlayState {
  const [isOpen, setOpenState] = useState(defaultOpen)
  const setOpen = useCallback((v: boolean) => { setOpenState(v); onOpenChange?.(v) }, [onOpenChange])
  return {
    isOpen,
    open: () => setOpen(true),
    close: () => setOpen(false),
    toggle: () => setOpen(!isOpen),
    setOpen,
  }
}

interface ModalContextValue extends OverlayState {}

const ModalContext = createContext<ModalContextValue | null>(null)

function useModal(): ModalContextValue {
  const ctx = useContext(ModalContext)
  if (!ctx) throw new Error("useModal, <Modal> içinde kullanılmalı")
  return ctx
}

/* ---------- Ana bileşen ---------- */

interface ModalProps {
  /** İlk çocuk = trigger; ikinci çocuk = Backdrop */
  children?: ReactNode
}

function Modal({ children }: ModalProps) {
  const state = useOverlayState()

  const kids = Children.toArray(children)
  const trigger = kids[0] as ReactElement | undefined
  const backdrop = kids[1] as ReactElement | undefined

  const triggerWithHandler = trigger
    ? cloneElement(trigger, { onClick: () => state.open() } as Record<string, unknown>)
    : null

  return (
    <ModalContext.Provider value={state}>
      {state.isOpen && backdrop ? cloneElement(backdrop, {} as Record<string, unknown>) : triggerWithHandler}
    </ModalContext.Provider>
  )
}

/* ---------- Trigger (özel) ---------- */

interface ModalTriggerProps {
  children?: ReactNode
  className?: string
}

function ModalTrigger({ children, className }: ModalTriggerProps) {
  const ctx = useModal()
  return (
    <div data-slot="modal-trigger" className={className} onClick={ctx.open}>
      {children}
    </div>
  )
}

/* ---------- Backdrop ---------- */

interface ModalBackdropProps {
  children?: ReactNode
  className?: string
  variant?: BackdropVariant
  isDismissable?: boolean
  isKeyboardDismissDisabled?: boolean
  isOpen?: boolean
  onOpenChange?: (v: boolean) => void
  UNSTABLE_portalContainer?: HTMLElement | null
}

const backdropVariantClass: Record<BackdropVariant, string> = {
  opaque: "bg-black/50",
  blur: "bg-black/30 backdrop-blur-sm",
  transparent: "bg-transparent",
}

function ModalBackdrop({
  children,
  className,
  variant = "opaque",
  isDismissable = true,
  isKeyboardDismissDisabled = false,
  isOpen,
  onOpenChange,
  UNSTABLE_portalContainer,
}: ModalBackdropProps) {
  const parent = useContext(ModalContext)
  const localCtx: ModalContextValue = {
    isOpen: isOpen ?? false,
    open: () => onOpenChange?.(true),
    close: () => onOpenChange?.(false),
    toggle: () => onOpenChange?.(!(isOpen ?? false)),
    setOpen: (v) => onOpenChange?.(v),
  }
  const ctx = parent ?? localCtx

  const open = isOpen ?? ctx.isOpen
  const setOpen = onOpenChange ?? ctx.setOpen

  // ESC + scroll lock
  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !isKeyboardDismissDisabled) setOpen(false)
    }
    window.addEventListener("keydown", onKey)
    const prev = document.body.style.overflow
    document.body.style.overflow = "hidden"
    return () => {
      window.removeEventListener("keydown", onKey)
      document.body.style.overflow = prev
    }
  }, [open, isKeyboardDismissDisabled, setOpen])

  if (!open) return null

  const backdropEl = (
    <ModalContext.Provider value={ctx}>
      <div
        data-slot="modal-backdrop"
        data-variant={variant}
        data-entering=""
        className={cn(
          "fixed inset-0 z-50 flex items-center justify-center p-4 data-[entering]:animate-in data-[entering]:fade-in data-[entering]:duration-200",
          backdropVariantClass[variant],
          className
        )}
        onClick={() => isDismissable && setOpen(false)}
      >
        {children}
      </div>
    </ModalContext.Provider>
  )

  return createPortal(backdropEl, UNSTABLE_portalContainer ?? document.body)
}

/* ---------- Container ---------- */

interface ModalContainerProps {
  children?: ReactNode
  className?: string
  placement?: ModalPlacement
  size?: ModalSize
  scroll?: ModalScroll
}

const placementClass: Record<ModalPlacement, string> = {
  auto: "items-center",
  center: "items-center",
  top: "items-start pt-12",
  bottom: "items-end pb-12",
}

const sizeClass: Record<ModalSize, string> = {
  xs: "max-w-[280px]",
  sm: "max-w-sm",
  md: "max-w-md",
  lg: "max-w-lg",
  cover: "w-full max-w-none sm:m-10",
  full: "w-full max-w-none h-full",
}

function ModalContainer({ children, className, placement = "auto", size = "md", scroll = "inside" }: ModalContainerProps) {
  return (
    <div
      data-slot="modal-container"
      data-placement={placement}
      data-size={size}
      data-scroll={scroll}
      data-entering=""
      className={cn(
        "flex w-full justify-center data-[entering]:animate-in data-[entering]:fade-in-0 data-[entering]:zoom-in-95 data-[entering]:duration-300",
        placementClass[placement],
        sizeClass[size],
        className
      )}
    >
      {children}
    </div>
  )
}

/* ---------- Dialog ---------- */

interface ModalDialogProps {
  children?: ReactNode | ((renderProps: { close: () => void }) => ReactNode)
  className?: string
  role?: string
  "aria-label"?: string
  "aria-labelledby"?: string
  "aria-describedby"?: string
}

function ModalDialog({ children, className, role = "dialog", ...aria }: ModalDialogProps) {
  const ctx = useModal()
  return (
    <div
      data-slot="modal-dialog"
      role={role}
      tabIndex={-1}
      className={cn("relative w-full rounded-xl border border-border bg-background text-foreground shadow-2xl outline-none", className)}
      {...aria}
    >
      {typeof children === "function" ? children({ close: ctx.close }) : children}
    </div>
  )
}

/* ---------- Compound parçalar ---------- */

function ModalHeader({ className, children }: { className?: string; children?: ReactNode }) {
  return <div data-slot="modal-header" className={cn("flex items-center gap-3 border-b border-border p-4", className)}>{children}</div>
}

function ModalIcon({ className, children }: { className?: string; children?: ReactNode }) {
  return (
    <span data-slot="modal-icon" className={cn("inline-flex size-10 shrink-0 items-center justify-center rounded-full bg-muted text-foreground", className)}>
      {children}
    </span>
  )
}

function ModalHeading({ className, children }: { className?: string; children?: ReactNode }) {
  return <h2 data-slot="modal-heading" className={cn("text-base font-semibold", className)}>{children}</h2>
}

function ModalBody({ className, children }: { className?: string; children?: ReactNode }) {
  return <div data-slot="modal-body" className={cn("overflow-y-auto p-4 text-sm text-muted-foreground", className)}>{children}</div>
}

function ModalFooter({ className, children }: { className?: string; children?: ReactNode }) {
  const ctx = useModal()
  return (
    <div data-slot="modal-footer" className={cn("flex items-center justify-end gap-2 border-t border-border p-4", className)}>
      {Children.map(children, (child) => {
        if (isValidElement(child) && (child.props as Record<string, unknown>).slot === "close") {
          return cloneElement(child, { onPress: ctx.close } as Record<string, unknown>)
        }
        return child
      })}
    </div>
  )
}

function ModalCloseTrigger({ className }: { className?: string }) {
  const ctx = useModal()
  return (
    <button
      type="button"
      aria-label="Kapat"
      onClick={ctx.close}
      className={cn(
        "absolute top-3 right-3 inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors outline-none hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50",
        className
      )}
    >
      <X className="size-4" aria-hidden="true" />
    </button>
  )
}

export {
  Modal,
  ModalBackdrop,
  ModalBody,
  ModalCloseTrigger,
  ModalContainer,
  ModalDialog,
  ModalFooter,
  ModalHeader,
  ModalHeading,
  ModalIcon,
  ModalTrigger,
  useModal,
  useOverlayState,
}
export type { BackdropVariant, ModalContainerProps, ModalDialogProps, ModalPlacement, ModalProps, ModalScroll, ModalSize, OverlayState }

/**
 * Popover
 * Saf React bileşen (bağımlılıksız).
 * Buton veya özel öğe ile tetiklenen zengin içerik balonu — trigger'a göre konumlanır.
 *   <Popover>
 *     <Button>Click me</Button>
 *     <PopoverContent placement="bottom" offset={8}>
 *       <PopoverDialog>
 *         <PopoverArrow />
 *         <PopoverHeading>Başlık</PopoverHeading>
 *         <p>İçerik…</p>
 *       </PopoverDialog>
 *     </PopoverContent>
 *   </Popover>
 * Özellikler: isOpen/defaultOpen/onOpenChange (kontrollü) · placement
 * (top/bottom/left/right) · offset · Content render prop · dışarı tıklama ile
 * kapanma · giriş animasyonu (tw-animate-css).
 * @id 447
 * @category Overlay
 * @subcategory Popover
 */
import {
  Children,
  cloneElement,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactElement,
  type ReactNode,
} from "react"
import { cn } from "@/lib/utils"

/* ---------- Types ---------- */

type PopoverPlacement = "top" | "bottom" | "left" | "right"

interface PopoverContextValue {
  isOpen: boolean
  open: () => void
  close: () => void
}

const PopoverContext = createContext<PopoverContextValue | null>(null)

function usePopover(): PopoverContextValue {
  const ctx = useContext(PopoverContext)
  if (!ctx) throw new Error("usePopover, <Popover> içinde kullanılmalı")
  return ctx
}

interface PopoverProps {
  children?: ReactNode
  isOpen?: boolean
  defaultOpen?: boolean
  onOpenChange?: (isOpen: boolean) => void
}

function Popover({ children, isOpen: isOpenProp, defaultOpen = false, onOpenChange }: PopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen)
  const isOpen = isOpenProp ?? internalOpen

  const open = useCallback(() => {
    setInternalOpen(true)
    onOpenChange?.(true)
  }, [onOpenChange])

  const close = useCallback(() => {
    setInternalOpen(false)
    onOpenChange?.(false)
  }, [onOpenChange])

  const contextValue: PopoverContextValue = { isOpen, open, close }

  const kids = Children.toArray(children)
  const trigger = kids[0] as ReactElement | undefined
  const content = kids[1] as ReactElement | undefined

  const triggerWithHandler = trigger
    ? cloneElement(trigger, { onClick: () => open() } as Record<string, unknown>)
    : null

  return (
    <PopoverContext.Provider value={contextValue}>
      <div data-slot="popover" className="relative inline-flex">
        {triggerWithHandler}
        {isOpen && content ? cloneElement(content, {} as Record<string, unknown>) : null}
      </div>
    </PopoverContext.Provider>
  )
}

/* ---------- Trigger (özel) ---------- */

interface PopoverTriggerProps {
  children?: ReactNode
  className?: string
  "aria-label"?: string
}

function PopoverTrigger({ children, className, ...props }: PopoverTriggerProps) {
  const ctx = usePopover()
  return (
    <div data-slot="popover-trigger" className={cn("cursor-pointer", className)} onClick={ctx.open} {...props}>
      {children}
    </div>
  )
}

/* ---------- Content ---------- */

interface PopoverContentProps {
  children?: ReactNode
  className?: string
  placement?: PopoverPlacement
  offset?: number
  shouldFlip?: boolean
  render?: (props: Record<string, unknown>) => ReactNode
}

const placementClass: Record<PopoverPlacement, string> = {
  bottom: "top-full left-0",
  top: "bottom-full left-0",
  left: "right-full top-0",
  right: "left-full top-0",
}

function PopoverContent({ children, className, placement = "bottom", offset = 8, render }: PopoverContentProps) {
  const ctx = usePopover()
  const dialogRef = useCallback((node: HTMLDivElement | null) => {
    if (!node) return
  }, [])

  // Dışarı tıklama ile kapat
  useEffect(() => {
    if (!ctx.isOpen) return
    const onDocClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (!target.closest("[data-slot=popover]")) ctx.close()
    }
    document.addEventListener("click", onDocClick)
    return () => document.removeEventListener("click", onDocClick)
  }, [ctx.isOpen, ctx])

  const marginStyle: Record<PopoverPlacement, React.CSSProperties> = {
    bottom: { marginTop: offset },
    top: { marginBottom: offset },
    left: { marginRight: offset },
    right: { marginLeft: offset },
  }

  const rootProps: Record<string, unknown> = {
    ref: dialogRef,
    "data-slot": "popover-content",
    "data-placement": placement,
    "data-entering": "",
    style: marginStyle[placement],
    className: cn(
      "absolute z-50 min-w-40 rounded-lg border border-border bg-background p-3 text-foreground shadow-xl",
      "data-[entering]:animate-in data-[entering]:fade-in-0 data-[entering]:zoom-in-95 data-[entering]:duration-200",
      placementClass[placement],
      className
    ),
  }

  const content = (
    <PopoverContext.Provider value={ctx}>{children}</PopoverContext.Provider>
  )

  if (render) return <>{render({ ...rootProps, children: content })}</>
  return <div {...rootProps}>{content}</div>
}

/* ---------- Dialog ---------- */

interface PopoverDialogProps {
  children?: ReactNode
  className?: string
}

function PopoverDialog({ children, className }: PopoverDialogProps) {
  return <div data-slot="popover-dialog" className={cn("text-sm", className)}>{children}</div>
}

/* ---------- Heading ---------- */

interface PopoverHeadingProps {
  children?: ReactNode
  className?: string
}

function PopoverHeading({ children, className }: PopoverHeadingProps) {
  return <h3 data-slot="popover-heading" className={cn("text-sm font-semibold", className)}>{children}</h3>
}

/* ---------- Arrow ---------- */

interface PopoverArrowProps {
  className?: string
}

function PopoverArrow({ className }: PopoverArrowProps) {
  return (
    <div
      data-slot="popover-arrow"
      aria-hidden="true"
      data-placement={undefined}
      className={cn(
        "absolute size-2 rotate-45 border-border bg-background",
        "top-[-5px] left-1/2 -ml-1 border-l border-t",
        className
      )}
    />
  )
}

export { Popover, PopoverArrow, PopoverContent, PopoverDialog, PopoverHeading, PopoverTrigger, usePopover }
export type { PopoverArrowProps, PopoverContentProps, PopoverDialogProps, PopoverProps }

/**
 * Tooltip
 * Saf React bileşen (bağımlılıksız).
 * Üzerine gelindiğinde/foküslandığında bilgilendirici metin gösterir.
 *   <Tooltip delay={0}>
 *     <Button>Hover me</Button>
 *     <TooltipContent placement="top" showArrow>
 *       <TooltipArrow />
 *       <p>Bu bir tooltip</p>
 *     </TooltipContent>
 *   </Tooltip>
 * Özellikler: delay/closeDelay · trigger (hover/focus) · isDisabled · placement
 * (top/bottom/left/right) · offset · showArrow · Content render prop.
 * @id 454
 * @category Overlay
 * @subcategory Tooltip
 */
import {
  Children,
  cloneElement,
  createContext,
  useContext,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react"
import { cn } from "@/lib/utils"

/* ---------- Types ---------- */

type TooltipPlacement = "top" | "bottom" | "left" | "right"

interface TooltipContextValue {
  isOpen: boolean
  open: () => void
  close: () => void
}

const TooltipContext = createContext<TooltipContextValue | null>(null)

function useTooltip(): TooltipContextValue {
  const ctx = useContext(TooltipContext)
  if (!ctx) throw new Error("useTooltip, <Tooltip> içinde kullanılmalı")
  return ctx
}

interface TooltipProps {
  children?: ReactNode
  /** Gösterim gecikmesi (ms) */
  delay?: number
  closeDelay?: number
  trigger?: "hover" | "focus"
  isDisabled?: boolean
}

function Tooltip({ children, delay = 700, closeDelay = 0, trigger = "hover", isDisabled = false }: TooltipProps) {
  const [isOpen, setIsOpen] = useState(false)
  const showTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const hideTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const open = () => {
    if (isDisabled) return
    if (hideTimer.current) clearTimeout(hideTimer.current)
    showTimer.current = setTimeout(() => setIsOpen(true), delay)
  }

  const close = () => {
    if (showTimer.current) clearTimeout(showTimer.current)
    hideTimer.current = setTimeout(() => setIsOpen(false), closeDelay)
  }

  const contextValue: TooltipContextValue = { isOpen, open, close }

  const kids = Children.toArray(children)
  const triggerEl = kids[0] as ReactElement | undefined
  const content = kids[1] as ReactElement | undefined

  const triggerProps: Record<string, unknown> = {}
  if (trigger === "hover") {
    triggerProps.onMouseEnter = open
    triggerProps.onMouseLeave = close
  } else {
    triggerProps.onFocus = open
    triggerProps.onBlur = close
  }
  const triggerWithHandlers = triggerEl ? cloneElement(triggerEl, triggerProps) : null

  return (
    <TooltipContext.Provider value={contextValue}>
      <div data-slot="tooltip" className="relative inline-flex">
        {triggerWithHandlers}
        {isOpen && content ? cloneElement(content, {} as Record<string, unknown>) : null}
      </div>
    </TooltipContext.Provider>
  )
}

/* ---------- Trigger ---------- */

interface TooltipTriggerProps {
  children?: ReactNode
  className?: string
  "aria-label"?: string
}

function TooltipTrigger({ children, className, ...props }: TooltipTriggerProps) {
  const ctx = useTooltip()
  return (
    <div
      data-slot="tooltip-trigger"
      className={cn("cursor-help", className)}
      onMouseEnter={ctx.open}
      onMouseLeave={ctx.close}
      onFocus={ctx.open}
      onBlur={ctx.close}
      {...props}
    >
      {children}
    </div>
  )
}

/* ---------- Content ---------- */

interface TooltipContentProps {
  children?: ReactNode
  className?: string
  placement?: TooltipPlacement
  offset?: number
  showArrow?: boolean
  render?: (props: Record<string, unknown>) => ReactNode
}

const placementClass: Record<TooltipPlacement, string> = {
  top: "bottom-full left-1/2 -translate-x-1/2",
  bottom: "top-full left-1/2 -translate-x-1/2",
  left: "right-full top-1/2 -translate-y-1/2",
  right: "left-full top-1/2 -translate-y-1/2",
}

const marginStyle: Record<TooltipPlacement, React.CSSProperties> = {
  top: { marginBottom: 6 },
  bottom: { marginTop: 6 },
  left: { marginRight: 6 },
  right: { marginLeft: 6 },
}

function TooltipContent({ children, className, placement = "top", offset, showArrow = false, render }: TooltipContentProps) {
  const ctx = useTooltip()
  const margin = marginStyle[placement]
  const o = offset ?? (showArrow ? 7 : 3)
  const style: React.CSSProperties =
    placement === "top"
      ? { marginBottom: o }
      : placement === "bottom"
        ? { marginTop: o }
        : placement === "left"
          ? { marginRight: o }
          : { marginLeft: o }

  const rootProps: Record<string, unknown> = {
    "data-slot": "tooltip-content",
    "data-placement": placement,
    "data-entering": "",
    style: { ...margin, ...style },
    className: cn(
      "absolute z-50 whitespace-nowrap rounded-md bg-foreground px-2.5 py-1.5 text-xs font-medium text-background shadow-lg",
      "data-[entering]:animate-in data-[entering]:fade-in-0 data-[entering]:zoom-in-95 data-[entering]:duration-150",
      placementClass[placement],
      className
    ),
  }

  const content = <TooltipContext.Provider value={ctx}>{children}</TooltipContext.Provider>

  if (render) return <>{render({ ...rootProps, children: content })}</>
  return <div {...rootProps}>{content}</div>
}

/* ---------- Arrow ---------- */

interface TooltipArrowProps {
  className?: string
}

function TooltipArrow({ className }: TooltipArrowProps) {
  return (
    <span
      data-slot="tooltip-arrow"
      aria-hidden="true"
      className={cn(
        "absolute size-1.5 rotate-45 bg-foreground",
        "top-[-3px] left-1/2 -ml-[3px]",
        className
      )}
    />
  )
}

export { Tooltip, TooltipArrow, TooltipContent, TooltipTrigger, useTooltip }
export type { TooltipArrowProps, TooltipContentProps, TooltipProps }

